import React from 'react';
import PropTypes from "prop-types";
import classNames from 'classnames';
import find from 'lodash/find';
import { useInnerText } from '../../inner_text';
export var EuiRangeTicks = ({
  disabled,
  onChange,
  ticks,
  tickSequence,
  value,
  max,
  min,
  interval = 1
}) => {
  // Calculate the width of each tick mark
  const percentageWidth = interval / (max - min + interval) * 100; // Align with item labels across the range by adding
  // left and right negative margins that is half of the tick marks

  const ticksStyle = !!ticks ? undefined : {
    margin: `0 ${percentageWidth / -2}%`,
    left: 0,
    right: 0
  };
  return <div className="euiRangeTicks" style={ticksStyle}>
      {tickSequence.map(tickValue => {
      const tickStyle = {};
      let customTick;

      if (ticks) {
        customTick = find(ticks, o => o.value === tickValue);

        if (customTick) {
          tickStyle.left = `${(customTick.value - min) / (max - min) * 100}%`;
        }
      } else {
        tickStyle.width = `${percentageWidth}%`;
      }

      const tickClasses = classNames('euiRangeTick', {
        'euiRangeTick--selected': value === tickValue,
        'euiRangeTick--isCustom': customTick
      });
      const label = customTick ? customTick.label : tickValue;
      const [ref, innerText] = useInnerText();
      return <button type="button" className={tickClasses} key={tickValue} value={tickValue} disabled={disabled} onClick={onChange} style={tickStyle} tabIndex={-1} ref={ref} title={typeof label === 'string' ? label : innerText}>
            {label}
          </button>;
    })}
    </div>;
};
EuiRangeTicks.propTypes = {
  ticks: PropTypes.arrayOf(PropTypes.shape({
    value: PropTypes.number.isRequired,
    label: PropTypes.node.isRequired
  }).isRequired),
  tickSequence: PropTypes.arrayOf(PropTypes.number.isRequired).isRequired,
  value: PropTypes.oneOfType([PropTypes.number.isRequired, PropTypes.string.isRequired, PropTypes.arrayOf(PropTypes.oneOfType([PropTypes.string.isRequired, PropTypes.number.isRequired]).isRequired).isRequired]),
  min: PropTypes.number.isRequired,
  max: PropTypes.number.isRequired,
  interval: PropTypes.number,
  disabled: PropTypes.bool,
  onChange: PropTypes.func
};