module.exports = "import React from 'react';\n\nimport {\n  EuiBreadcrumbs,\n  EuiSpacer,\n  EuiTitle,\n} from '../../../../src/components';\n\nexport default () => {\n  const breadcrumbs = [\n    {\n      text: 'Animals',\n      href: '#',\n    },\n    {\n      text:\n        'Metazoans is a real mouthful, especially for creatures without mouths',\n      href: '#',\n      truncate: true,\n    },\n    {\n      text: 'Chordates',\n      href: '#',\n    },\n    {\n      text: 'Vertebrates',\n      href: '#',\n    },\n    {\n      text: 'Tetrapods',\n      href: '#',\n    },\n    {\n      text: 'Reptiles',\n      href: '#',\n    },\n    {\n      text: 'Boa constrictor',\n      href: '#',\n    },\n    {\n      text:\n        'Nebulosa subspecies is also a real mouthful, especially for creatures without mouths',\n    },\n  ];\n\n  return (\n    <div>\n      <EuiTitle size=\"xs\">\n        <span>Truncation on a single item</span>\n      </EuiTitle>\n      <EuiSpacer size=\"s\" />\n      <EuiBreadcrumbs\n        responsive={false}\n        truncate={false}\n        breadcrumbs={breadcrumbs}\n      />\n      <EuiSpacer />\n      <EuiTitle size=\"xs\">\n        <span>Truncation on the entire set</span>\n      </EuiTitle>\n      <EuiSpacer size=\"s\" />\n      <EuiBreadcrumbs\n        responsive={false}\n        truncate={true}\n        breadcrumbs={breadcrumbs}\n      />\n    </div>\n  );\n};\n"