module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButton,\n  EuiCode,\n  EuiPanel,\n  EuiPopover,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport default class PopoverContainer extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n    };\n  }\n\n  onButtonClick = () => {\n    this.setState({\n      isPopoverOpen: !this.state.isPopoverOpen,\n    });\n  };\n\n  closePopover = () => {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  };\n\n  setPanelRef = node => (this.panel = node);\n\n  render() {\n    const button = (\n      <EuiButton\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.onButtonClick}\n        style={{ position: 'relative', left: 50 }}>\n        Show constrained popover\n      </EuiButton>\n    );\n\n    return (\n      <EuiPanel panelRef={this.setPanelRef}>\n        <EuiPopover\n          id=\"popover\"\n          button={button}\n          isOpen={this.state.isPopoverOpen}\n          closePopover={this.closePopover}\n          container={this.panel}>\n          <div>\n            Popover is positioned <EuiCode>downCenter</EuiCode> but constrained\n            to fit within the panel.\n          </div>\n        </EuiPopover>\n\n        {/* create adequate room for the popover */}\n        <EuiSpacer size=\"xxl\" />\n        <EuiSpacer size=\"xxl\" />\n      </EuiPanel>\n    );\n  }\n}\n"