module.exports = "import React, { useState } from 'react';\nimport {\n  EuiButton,\n  EuiDragDropContext,\n  EuiDraggable,\n  EuiDroppable,\n} from '../../../../src/components';\n\nimport { reorder } from '../../../../src/components/drag_and_drop';\n\nimport { makeList } from './helper';\n\nexport default () => {\n  const [list, setList] = useState(makeList(3));\n  const onDragEnd = ({ source, destination }) => {\n    if (source && destination) {\n      const items = reorder(list, source.index, destination.index);\n\n      setList(items);\n    }\n  };\n  return (\n    <EuiDragDropContext onDragEnd={onDragEnd}>\n      <EuiDroppable\n        droppableId=\"DROPPABLE_AREA\"\n        spacing=\"m\"\n        withPanel\n        grow={false}>\n        {list.map(({ content, id }, idx) => (\n          <EuiDraggable\n            spacing=\"m\"\n            key={id}\n            index={idx}\n            draggableId={id}\n            disableInteractiveElementBlocking>\n            <EuiButton fullWidth onClick={() => alert(`${content} clicked!`)}>\n              {content}\n            </EuiButton>\n          </EuiDraggable>\n        ))}\n      </EuiDroppable>\n    </EuiDragDropContext>\n  );\n};\n"