module.exports = "import React, { Fragment } from 'react';\n\nimport {\n  EuiSpacer,\n  EuiCodeBlock,\n  EuiText,\n  prettyDuration,\n} from '../../../../src/components';\n\nconst examples = [\n  {\n    start: '2018-01-17T18:57:57.149Z',\n    end: '2018-01-17T20:00:00.000Z',\n    quickRanges: [],\n    dateFormat: 'MMMM Do YYYY, HH:mm:ss.SSS',\n  },\n  {\n    start: '2018-01-17T18:57:57.149Z',\n    end: '2018-01-17T20:00:00.000Z',\n    quickRanges: [],\n    dateFormat: 'MMMM Do YYYY @ HH:mm:ss.SSS',\n  },\n  {\n    start: '2018-01-17T18:57:57.149Z',\n    end: 'now-2h',\n    quickRanges: [],\n    dateFormat: 'MMMM Do YYYY @ HH:mm:ss.SSS',\n  },\n  {\n    start: 'now-17m',\n    end: 'now',\n    quickRanges: [],\n    dateFormat: 'MMMM Do YYYY @ HH:mm:ss.SSS',\n  },\n  {\n    start: 'now-17m',\n    end: 'now-1m',\n    quickRanges: [],\n    dateFormat: 'MMMM Do YYYY @ HH:mm:ss.SSS',\n  },\n  {\n    start: 'now-15m',\n    end: 'now',\n    quickRanges: [\n      {\n        start: 'now-15m',\n        end: 'now',\n        label: 'quick range 15 minutes custom display',\n      },\n    ],\n    dateFormat: 'MMMM Do YYYY, HH:mm:ss.SSS',\n  },\n];\n\nexport default function prettyDurationExample() {\n  return (\n    <Fragment>\n      {examples.map(({ start, end, quickRanges, dateFormat }, idx) => (\n        <div key={idx}>\n          <EuiCodeBlock paddingSize=\"s\">\n            prettyDuration(&apos;{start}&apos;, &apos;{end}&apos;,{' '}\n            {JSON.stringify(quickRanges)}, &apos;\n            {dateFormat}&apos;)\n          </EuiCodeBlock>\n\n          <EuiSpacer size=\"s\" />\n\n          <EuiText>\n            <p>{prettyDuration(start, end, quickRanges, dateFormat)}</p>\n          </EuiText>\n\n          <EuiSpacer size=\"xl\" />\n        </div>\n      ))}\n    </Fragment>\n  );\n}\n"